/// signal SpinButton.input: GtkSpinButton::input, run-last, returns gint with a gdouble* out parameter: 1 = converted, 0 = not handled, GTK_INPUT_ERROR (-1) = failed (Gtk 4 docs); gtk_spin_button_update emits it
#[test]
fn signal_spinbutton_input() {
    on_gtk(|| {
        let mut h = Harness::new();
        let e = h.create("spinbutton");
        let o = e;
        
        let fire = |o: &gtk::glib::Object, v: &str, i: usize| {
            let _ = (v, i);
            let s = o.downcast_ref::<gtk::SpinButton>().unwrap(); s.set_range(0.0, 100.0); s.update();
        };
        assert_ne!(h.resolve_signal("spinbutton", "input"), 0);
        assert_eq!(h.resolve_signal("spinbutton", "input"), h.resolve_signal("spinbutton", "input"));
        h.listen(e, "input", true).unwrap();
        fire(&h.obj(e), "a", 0);
        // GTK may emit a signal several times per edit (e.g. delete + insert for set_text).
        let ev = h.take_events();
        assert!(!ev.is_empty() && ev.iter().all(|x| *x == (e, "input".to_string())), "delivered: {ev:?}");
        h.listen(e, "input", false).unwrap();
        fire(&h.obj(e), "b", 1);
        assert!(h.take_events().is_empty(), "no delivery after listen(off)");
        h.listen(e, "input", true).unwrap();
        let obj = h.obj(e);
        h.destroy(e);
        fire(&obj, "c", 2);
        assert!(h.take_events().is_empty(), "handler is disconnected on destroy");
        assert!(h.listen(e, "input", true).is_err(), "stale handle is an error");
    });
}

